	def asis_files = ["app/proguard-android.text",
		"baseBuildAdditions.gradle", "buildscriptAdditions.gradle", "local.properties",
		"gradlew", "gradlew.bat", "rungradle.bat"] as String[]
	asis_files.eachWithIndex { v, i ->
		asis_infile = new File(rootProject.projectDir, v)
		if (asis_infile.exists()) {
			asis_outfile = new File(rootProject.projectDir, "ASISProject/" + v)
			asis_outfile.withWriter { writer ->
				asis_infile.withReader { reader ->
					while ((asis_line = reader.readLine()) != null) {
						writer.writeLine("${asis_line}")
					}
				}
			}
		}
	}


	public int AndroidThunkJava_AndroidSingleInstanceServer_IsRunning()
	{
        Set<Thread> threads = Thread.getAllStackTraces().keySet();
		int ConnectionType = 0;
        for (Thread thread : threads) {
            String name = thread.getName();
            if (name.contains("unrealSharedInstanceService"))
            {
                if (thread.isAlive()) {
					ConnectionType |= 1;
                }
            }
        }

		return ConnectionType;
	}

	public boolean AndroidThunkJava_AndroidSingleInstanceServer_Stop()
	{
        Set<Thread> threads = Thread.getAllStackTraces().keySet();
        boolean bFoundThread = false;
        for (Thread thread : threads) {
            String name = thread.getName();
            if (name.contains("unrealSharedInstanceService"))
            {
                if (thread.isAlive()) {
					thread.interrupt();
                    bFoundThread = true;
                }
            }
        }

		return bFoundThread;
	}

